              <tr><td class="p-2 border font-mono">K/0</td><td class="p-2 border">Kawin, 0 Tanggungan</td><td class="p-2 border">Rp 58.500.000</td><td class="p-2 border font-bold text-emerald-700">Kategori A</td></tr>
